(()=>{function suitSVG(s){let paths={'♠':'M12 1C8 6 1 9 1 15c0 6 7 7 10 2-1 5-3 6-4 6h10c-1 0-3-1-4-6 3 5 10 4 10-2C23 9 16 6 12 1z','♥':'M12 22S1 14 1 7C1 0 9-1 12 5c3-6 11-5 11 2 0 7-11 15-11 15z','♦':'M12 1L23 12 12 23 1 12z','♣':'M12 1a5 5 0 0 1 4 9 6 6 0 1 1-3 8c1 4 2 5 4 5H7c2 0 3-1 4-5a6 6 0 1 1-3-8 5 5 0 0 1 4-9z'};return `<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path fill="currentColor" d="${paths[s]||paths['♠']}"></path></svg>`}
function card(c,mini=false){if(c==='?')return `<span class="pc back ${mini?'mini':''}" role="img" aria-label="尚未揭曉的牌"></span>`;const r=c[0],s=c.slice(1),rank=r==='T'?'10':r,name={'♠':'黑桃','♥':'紅心','♦':'方塊','♣':'梅花'}[s]||'';const icon=(x,y,w,h)=>suitSVG(s).replace('<svg ',`<svg x="${x}" y="${y}" width="${w}" height="${h}" `);return `<span class="pc ${/[♥♦]/.test(s)?'red':''} ${mini?'mini':''}" role="img" aria-label="${name}${rank}"><svg class="card-art" viewBox="0 0 60 86" width="60" height="86" preserveAspectRatio="xMidYMid meet" aria-hidden="true" focusable="false"><g fill="currentColor" font-family="Arial, sans-serif" font-weight="700"><text x="5" y="15" font-size="14">${rank}</text>${icon(5,18,9,10)}${icon(18,29,24,28)}<g transform="translate(60 86) rotate(180)"><text x="5" y="15" font-size="14">${rank}</text>${icon(5,18,9,10)}</g></g></svg></span>`}
window.SSCardMarkup=card})();